const fs = require('fs');
function readJson(path, fallback) {
  try { return JSON.parse(fs.readFileSync(path, 'utf8')); } catch (e) { return fallback; }
}
function dhakaDate(iso) {
  try { return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Dhaka', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(iso)); } catch (e) { return ''; }
}
const today = dhakaDate(new Date().toISOString());
const news = readJson('/agency/news-log.json', { entries: [] });
const deals = readJson('/agency/deals-log.json', { entries: [] });
const manual = readJson('/agency/earnings-manual.json', { earnings: [] });
const newsEntries = Array.isArray(news.entries) ? news.entries : [];
const dealEntries = Array.isArray(deals.entries) ? deals.entries : [];
const manualEntries = Array.isArray(manual.earnings) ? manual.earnings : [];
const newsToday = newsEntries.filter(e => e.status === 'posted' && dhakaDate(e.ts) === today).length;
const dealsToday = dealEntries.filter(e => e.status === 'posted' && dhakaDate(e.ts) === today).length;
const totalNews = newsEntries.filter(e => e.status === 'posted').length;
const totalDeals = dealEntries.filter(e => e.status === 'posted').length;
const earningsToday = manualEntries.filter(e => (e.date || '') === today).reduce((s, e) => s + (Number(e.amount_bdt) || 0), 0);
const earningsTotal = manualEntries.reduce((s, e) => s + (Number(e.amount_bdt) || 0), 0);
const summary = { date: today, news_posts_today: newsToday, deals_posts_today: dealsToday,
  total_news_posts: totalNews, total_deals_posts: totalDeals,
  earnings_bdt_today: earningsToday, earnings_bdt_total: earningsTotal,
  earnings_source: manualEntries.some(e => (e.date || '') === today)
    ? 'manual (Daraz affiliate dashboard — entered by Jony in /agency/earnings-manual.json)'
    : 'none — no manual earnings entered for today (Daraz has no public earnings API)',
  target_usd_per_day: 0.10,
  target_note: '$0.10/day is about ৳12/day at ~৳120/USD (approx — rate varies). Earnings are only known from the Daraz dashboard; this tracker logs activity + manually entered earnings and never invents earnings.',
  ts: new Date().toISOString() };
const profit = readJson('/agency/profit-log.json', { days: [] });
if (!Array.isArray(profit.days)) profit.days = [];
const idx = profit.days.findIndex(d => d.date === today);
if (idx >= 0) profit.days[idx] = summary; else profit.days.push(summary);
profit.days = profit.days.slice(-365);
try { fs.writeFileSync('/agency/profit-log.json', JSON.stringify(profit, null, 2)); } catch (e) {}
return [{ json: summary }];
